//! The bridge between the typed queries (`fafnirx-db`, generated by Cornucopia from `queries/*.sql`) and the
//! `postgres` clients the rest of the master passes around.

use postgres::types::{BorrowToSql, ToSql};
use postgres::{Error, GenericClient, Row, RowIter, Statement, ToStatement};

/// Runs generated queries on any `postgres` client or transaction: `query().bind(&mut Pg(conn), ...)`.
pub struct Pg<'a, C>(pub &'a mut C);

impl<C: GenericClient> fafnirx_db::client::GenericClient for Pg<'_, C> {
    fn prepare(&mut self, query: &str) -> Result<Statement, Error> {
        self.0.prepare(query)
    }
    fn execute<T>(&mut self, query: &T, params: &[&(dyn ToSql + Sync)]) -> Result<u64, Error>
    where
        T: ?Sized + ToStatement,
    {
        self.0.execute(query, params)
    }
    fn query_one<T>(&mut self, statement: &T, params: &[&(dyn ToSql + Sync)]) -> Result<Row, Error>
    where
        T: ?Sized + ToStatement,
    {
        self.0.query_one(statement, params)
    }
    fn query_opt<T>(&mut self, statement: &T, params: &[&(dyn ToSql + Sync)]) -> Result<Option<Row>, Error>
    where
        T: ?Sized + ToStatement,
    {
        self.0.query_opt(statement, params)
    }
    fn query<T>(&mut self, query: &T, params: &[&(dyn ToSql + Sync)]) -> Result<Vec<Row>, Error>
    where
        T: ?Sized + ToStatement,
    {
        self.0.query(query, params)
    }
    fn query_raw<T, P, I>(&mut self, statement: &T, params: I) -> Result<RowIter<'_>, Error>
    where
        T: ?Sized + ToStatement,
        P: BorrowToSql,
        I: IntoIterator<Item = P>,
        I::IntoIter: ExactSizeIterator,
    {
        self.0.query_raw(statement, params)
    }
}
